import React from 'react';

const Navbar = () => {
  return (
    <nav className="bg-white shadow-md p-4">
      <div className="container mx-auto flex justify-between items-center">
        {/* Logo */}
        <div className="text-2xl font-bold text-blue-600">
          🚗 RentCar
        </div>

        {/* Menü */}
        <div className="flex space-x-6">
          <a href="/arac-kontrol" className="text-gray-700 hover:text-blue-600">Araç Kontrol</a>
          <a href="/login" className="text-gray-700 hover:text-blue-600">Giriş Yap</a>
          <a href="/mobiliz" className="text-gray-700 hover:text-blue-600">Mobiliz</a>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
